import pandas as pd,numpy as np,json
from pathlib import Path
O=Path('outputs');W=Path('work');ref=pd.read_csv(O/'stage6_foxp2_gnomad_narrow_variants.csv');g=pd.read_csv(W/'stage6_foxp2_susie_aligned.csv');g=ref[['rs']].merge(g,on='rs',validate='one_to_one');cols=['chromosome','pos','effect','other','beta','se','eaf','p','col9','col10','col11','col12','col13','col14','col15'];q=pd.read_csv(W/'stage6_portas_nrem_foxp2_region.tsv.gz',sep='\t',header=None,names=cols);q=q[q.effect.isin(['A','C','G','T'])&q.other.isin(['A','C','G','T'])&(q.se>0)].copy();q['pair']=q.apply(lambda r:''.join(sorted([r.effect,r.other])),axis=1);g['pair']=g.apply(lambda r:''.join(sorted([r.anchor_effect_allele,r.anchor_other_allele])),axis=1);x=g.merge(q,on=['pos','pair'],validate='one_to_many');x['nrem_beta_anchor']=np.where(x.effect==x.anchor_effect_allele,x.beta,-x.beta);x['nrem_eaf_anchor']=np.where(x.effect==x.anchor_effect_allele,x.eaf,1-x.eaf);x['nrem_z_anchor']=x.nrem_beta_anchor/x.se;nfe=pd.read_csv(O/'stage6_foxp2_gnomad_nfe_variant_index.csv');nfe['nfe_anchor_af']=np.where(nfe.sign_to_anchor==1,nfe.gnomad_af_alt,1-nfe.gnomad_af_alt);x=x.merge(nfe[['rs','nfe_anchor_af']],on='rs',validate='one_to_one');x['nrem_ref_diff']=(x.nrem_eaf_anchor-x.nfe_anchor_af).abs();dup=x.duplicated('rs',keep=False);assert not dup.any();x=x[x.nrem_ref_diff<=.2].copy();x.to_csv(O/'stage6_portas_nrem_foxp2_aligned.csv',index=False);rec={'n_gwas_reference':len(g),'n_exact_matched_before_af':len(g.merge(q,on=['pos','pair'])),'n_after_af':len(x),'mean_eaf_difference':float(x.nrem_ref_diff.mean()),'max_eaf_difference':float(x.nrem_ref_diff.max()),'rs12536335_present':bool(x.rs.eq('rs12536335').any()),'rs35624276_present':bool(x.rs.eq('rs35624276').any()),'working_n':80013};(O/'stage6_portas_nrem_foxp2_prepare_receipt.json').write_text(json.dumps(rec,indent=2)+'\n');print(rec)
